import json, time, urllib.request, urllib.error
from datetime import datetime, timezone

BASE = 'http://localhost:8080'
token = None

def get_token():
    global token
    while True:
        req = urllib.request.Request(BASE + '/token', method='POST')
        try:
            with urllib.request.urlopen(req, timeout=30) as res:
                data = json.loads(res.read())
                token = data['token']
                print('token refreshed', file=__import__('sys').stderr)
                return
        except urllib.error.HTTPError as e:
            if e.code == 429:
                wait = float(e.headers.get('Retry-After', '1'))
                print(f'rate limited token; waiting {wait}s', file=__import__('sys').stderr)
                time.sleep(wait)
                continue
            print(f'token error {e.code}; retrying', file=__import__('sys').stderr)
            time.sleep(1)
        except Exception as e:
            print(f'token request error {e}; retrying', file=__import__('sys').stderr)
            time.sleep(1)

def api_get(path):
    global token
    while True:
        if token is None:
            get_token()
        req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
        try:
            with urllib.request.urlopen(req, timeout=30) as res:
                return json.loads(res.read())
        except urllib.error.HTTPError as e:
            if e.code == 429:
                wait = float(e.headers.get('Retry-After', '1'))
                print(f'rate limited {path}; waiting {wait}s', file=__import__('sys').stderr)
                time.sleep(wait)
                continue
            if e.code == 401:
                print(f'token rejected {path}; refreshing', file=__import__('sys').stderr)
                token = None
                continue
            print(f'HTTP {e.code} for {path}; retrying', file=__import__('sys').stderr)
            time.sleep(1)
        except Exception as e:
            print(f'request error for {path}: {e}; retrying', file=__import__('sys').stderr)
            time.sleep(1)

# Walk every page, following the service's advertised total and next link.
orders = []
seen = set()
duplicates = 0
page = 1
total_pages = None
while True:
    payload = api_get(f'/orders?page={page}')
    if total_pages is None:
        total_pages = int(payload['total_pages'])
    if int(payload.get('page', -1)) "'!= page:
        print(f'"'unexpected page response for {page}; retrying', file=__import__('sys').stderr)
        continue
    for order in payload['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
        else:
            seen.add(oid)
            orders.append(order)
    if payload.get('next') is None:
        break
    page += 1

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
qualifying = []
for order in orders:
    if order['status'] "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if start <= placed < end:
        qualifying.append(order)

customers = {}
for order in qualifying:
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = api_get('/customers/' + cid)

regions = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    customer = customers[order['customer_id']]
    amount = int(order['amount_cents'])
    pct = int(customer['discount_pct'])
    discounted = (amount * (100 - pct) + 50) // 100
    regions[customer['region']] += discounted

result = {
    'total_cents': sum(regions.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': regions,
}
print(json.dumps(result, indent=2))
print(f'pages={total_pages}; unique_orders={len(orders)}; qualifying={len(qualifying)}; customers_cached={len(customers)}; duplicate_listings={duplicates}', file=__import__('sys').stderr)
